'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useId, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import {
  AlertCircleIcon,
  CheckIcon,
  PlusIcon,
  SendIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';

import { ActionButton, useTimedAction } from './_parts/action-button';
import { AddressField, type FieldChip } from './_parts/address-field';
import {
  ADDRESS_LOOK,
  mergeAddresses,
  splitAddresses,
  stateOfAddress,
  type AddressLook,
  type AddressState,
} from './_parts/invite-emails';
import {
  ModalDescription,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { chipVariantsOf, rowVariantsOf } from './_parts/motion';
import { PEOPLE, WORKSPACE_NAME } from './_parts/people';
import { PendingAvatar, PersonAvatar } from './_parts/person-avatar';
import { Swap } from './_parts/swap';

type InviteStatus = 'sent' | 'joined';

type RecentInvite = { email: string; status: InviteStatus };

type SeatState = 'used' | 'reserved' | 'free';

/** People in the workspace who are not in the recent list, each holding a seat. */
const OTHER_MEMBERS = 3;

const SEATS_PER_STEP = 5;

const RECENT_INVITES: RecentInvite[] = [
  { email: 'priya@lattice.example', status: 'joined' },
  { email: 'noor.haddad@lattice.example', status: 'sent' },
  { email: 'mateo@lattice.example', status: 'joined' },
  { email: 'kofi.mensah@lattice.example', status: 'sent' },
];

const NO_SEAT_LOOK: AddressLook = {
  color: 'var(--destructive)',
  icon: AlertCircleIcon,
  hint: 'No seat left for this address',
};

const MEMBER_EMAILS = new Set(PEOPLE.map((person) => person.email));

type FieldEntry = { email: string; state: AddressState; hasSeat: boolean };

function seatStateOf(index: number, used: number, reserved: number): SeatState {
  if (index < used) {
    return 'used';
  }
  const reservedEnd = used + reserved;
  if (index < reservedEnd) {
    return 'reserved';
  }
  return 'free';
}

const SEAT_CLASS: Record<SeatState, string> = {
  used: 'bg-primary border-transparent',
  reserved: 'hairline-border border-dashed border-primary bg-primary/10',
  free: 'bg-foreground/[0.08] border-transparent',
};

function lookOf(entry: FieldEntry): AddressLook {
  const isNew = entry.state === 'new';
  const lacksSeat = isNew && !entry.hasSeat;
  if (lacksSeat) {
    return NO_SEAT_LOOK;
  }
  return ADDRESS_LOOK[entry.state];
}

function entriesOf(
  addresses: string[],
  pendingEmails: ReadonlySet<string>,
  freeSeats: number
) {
  const context = { memberEmails: MEMBER_EMAILS, pendingEmails };
  const entries: FieldEntry[] = [];
  let seatsLeft = freeSeats;
  for (const email of addresses) {
    const state = stateOfAddress(email, context);
    const isNew = state === 'new';
    const hasSeat = isNew && seatsLeft > 0;
    if (hasSeat) {
      seatsLeft -= 1;
    }
    entries.push({ email, state, hasSeat });
  }
  return entries;
}

function seatLineOf(reserved: number, lacking: number, freeSeats: number) {
  if (lacking === 1) {
    return '1 address has no seat left. Add seats or remove it';
  }
  if (lacking > 1) {
    return `${lacking} addresses have no seat left. Add seats or remove them`;
  }
  if (reserved === 1) {
    return 'The address below takes 1 more seat';
  }
  if (reserved > 1) {
    return `The ${reserved} addresses below take ${reserved} more seats`;
  }
  if (freeSeats === 1) {
    return '1 seat left on your plan';
  }
  return `${freeSeats} seats left on your plan`;
}

function sendLabelOf(count: number) {
  if (count > 1) {
    return `Send ${count} invitations`;
  }
  return 'Send invitation';
}

const STATUS_LOOK: Record<
  InviteStatus,
  { label: string; color: string; hasCheck: boolean }
> = {
  sent: {
    label: 'Invite sent',
    color: 'var(--muted-foreground)',
    hasCheck: false,
  },
  joined: { label: 'Joined', color: 'var(--success)', hasCheck: true },
};

function RecentRow({ invite }: { invite: RecentInvite }) {
  const person = PEOPLE.find((candidate) => candidate.email === invite.email);
  const look = STATUS_LOOK[invite.status];

  return (
    <div className='flex min-h-12 items-center gap-3 px-3 py-2'>
      {person && <PersonAvatar person={person} />}
      {!person && <PendingAvatar email={invite.email} />}
      <p className='min-w-0 flex-1 truncate text-[13px]'>{invite.email}</p>
      <Chip color={look.color}>
        {look.hasCheck && <CheckIcon strokeWidth={2.5} />}
        {look.label}
      </Chip>
    </div>
  );
}

function SeatMeter({
  capacity,
  used,
  reserved,
  line,
  isShort,
  onAddSeats,
}: {
  capacity: number;
  used: number;
  reserved: number;
  line: string;
  isShort: boolean;
  onAddSeats: () => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const cellVariants = chipVariantsOf(shouldReduceMotion);
  const allowsLayout = !shouldReduceMotion;
  const labelId = useId();
  const addAction = useTimedAction();
  const seats = Array.from({ length: capacity }, (_, index) => index);

  function addSeats() {
    addAction.run(onAddSeats);
  }

  return (
    <div className='bg-foreground/[0.03] flex flex-col gap-3 rounded-xl p-4'>
      <div className='flex items-start gap-3'>
        <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
          <p id={labelId} className='text-sm font-medium tabular-nums'>
            <MotionNumber value={used} />
            {' of '}
            <MotionNumber value={capacity} />
            {' seats used'}
          </p>
          <Swap
            swapKey={line}
            kind='label'
            className={cn(
              'flex min-w-0 text-xs',
              isShort && 'text-destructive-ink',
              !isShort && 'text-muted-foreground'
            )}
            contentClassName='max-w-full min-w-0 whitespace-normal'
          >
            {line}
          </Swap>
        </div>
        <ActionButton
          variant='outline'
          size='sm'
          state={addAction.state}
          onClick={addSeats}
          idleIcon={<PlusIcon />}
          labels={{
            idle: `Add ${SEATS_PER_STEP} seats`,
            working: 'Adding',
            done: 'Added',
          }}
        />
      </div>
      <div
        role='meter'
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={capacity}
        aria-valuenow={used}
        className='flex gap-1'
      >
        <AnimatePresence initial={false}>
          {seats.map((index) => {
            const seatState = seatStateOf(index, used, reserved);

            return (
              <motion.span
                key={index}
                layout={allowsLayout}
                variants={cellVariants}
                initial='hidden'
                animate='shown'
                exit='hidden'
                className={cn(
                  'h-2 min-w-0 flex-1 rounded-full border transition-[background-color,border-color] duration-300 ease-(--ease-out-strong)',
                  SEAT_CLASS[seatState]
                )}
              />
            );
          })}
        </AnimatePresence>
      </div>
    </div>
  );
}

function InviteWithSeats() {
  const [capacity, setCapacity] = useState(10);
  const [recent, setRecent] = useState<RecentInvite[]>(RECENT_INVITES);
  const [addresses, setAddresses] = useState<string[]>([
    'ada.lindqvist@lattice.example',
    'bruno.costa@lattice.example',
    'lea.martin@lattice.example',
    'sami.k@lattice.example',
  ]);
  const action = useTimedAction();
  const shouldReduceMotion = useReducedMotion();
  const rowVariants = rowVariantsOf(shouldReduceMotion);
  const used = OTHER_MEMBERS + recent.length;
  const freeSeats = Math.max(0, capacity - used);
  const pendingEmails = new Set(recent.map((invite) => invite.email));
  const entries = entriesOf(addresses, pendingEmails, freeSeats);
  const seated = entries.filter((entry) => entry.hasSeat);
  const reserved = seated.length;
  const lackingEntries = entries.filter((entry) => {
    const isNew = entry.state === 'new';
    return isNew && !entry.hasSeat;
  });
  const lacking = lackingEntries.length;
  const isShort = lacking > 0;
  const line = seatLineOf(reserved, lacking, freeSeats);
  const chips: FieldChip[] = entries.map((entry) => ({
    email: entry.email,
    look: lookOf(entry),
  }));
  const canSend = reserved > 0;

  function addAddresses(text: string) {
    const added = splitAddresses(text);
    setAddresses((previous) => mergeAddresses(previous, added));
  }

  function removeAddress(email: string) {
    setAddresses((previous) => previous.filter((item) => item !== email));
  }

  function addSeats() {
    setCapacity((previous) => previous + SEATS_PER_STEP);
  }

  function commitSend() {
    const sentEmails = seated.map((entry) => entry.email);
    const created = sentEmails.map((email) => ({
      email,
      status: 'sent' as const,
    }));
    setRecent((previous) => [...created, ...previous]);
    setAddresses((previous) =>
      previous.filter((email) => !sentEmails.includes(email))
    );
  }

  function send(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!canSend) {
      return;
    }
    action.run(commitSend);
  }

  function sendFromShortcut() {
    if (!canSend) {
      return;
    }
    action.run(commitSend);
  }

  return (
    <>
      <ModalHeader>
        <ModalTitle>{`Invite people to ${WORKSPACE_NAME}`}</ModalTitle>
        <ModalDescription>
          Everyone who joins or is invited takes one seat of your plan
        </ModalDescription>
      </ModalHeader>
      <SeatMeter
        capacity={capacity}
        used={used}
        reserved={reserved}
        line={line}
        isShort={isShort}
        onAddSeats={addSeats}
      />
      <form onSubmit={send} autoComplete='off' className='flex flex-col gap-2'>
        <AddressField
          label='E-mail addresses'
          chips={chips}
          onAdd={addAddresses}
          onRemove={removeAddress}
          onSubmitShortcut={sendFromShortcut}
          isInvalid={isShort}
        />
        <div className='flex justify-end'>
          <ActionButton
            type='submit'
            state={action.state}
            disabled={!canSend}
            idleIcon={<SendIcon />}
            labels={{
              idle: sendLabelOf(reserved),
              working: 'Sending',
              done: 'Sent',
            }}
          />
        </div>
      </form>
      <section className='flex flex-col gap-2'>
        <h3 className='text-muted-foreground text-xs font-medium'>
          Recent invitations
        </h3>
        <ul className='bg-card hairline-ring ring-border flex flex-col overflow-hidden rounded-xl py-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
          <AnimatePresence initial={false}>
            {recent.map((invite) => (
              <motion.li
                key={invite.email}
                variants={rowVariants}
                initial='hidden'
                animate='shown'
                exit='hidden'
              >
                <RecentRow invite={invite} />
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      </section>
    </>
  );
}

export default function Modal02() {
  return (
    <ModalPreview triggerLabel='Open the seat limit dialog' size='lg'>
      <InviteWithSeats />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { CheckIcon, LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

export type ActionState = 'idle' | 'working' | 'done';

export type ActionLabels = Record<ActionState, string>;

const WORKING_MS = 800;

const DONE_MS = 1600;

/** The life of an action that takes a moment: working, then done for a beat, then ready again. The change is committed when the work ends. */
export function useTimedAction() {
  const [state, setState] = useState<ActionState>('idle');
  const commitRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (state === 'working') {
      const timeout = window.setTimeout(() => {
        const commit = commitRef.current;
        commitRef.current = null;
        if (commit) {
          commit();
        }
        setState('done');
      }, WORKING_MS);
      return () => window.clearTimeout(timeout);
    }
    if (state === 'done') {
      const timeout = window.setTimeout(() => {
        setState('idle');
      }, DONE_MS);
      return () => window.clearTimeout(timeout);
    }
  }, [state]);

  function run(commit: () => void) {
    if (state !== 'idle') {
      return;
    }
    commitRef.current = commit;
    setState('working');
  }

  const isBusy = state !== 'idle';

  return { state, run, isBusy };
}

function iconOf(state: ActionState, idleIcon: React.ReactNode) {
  if (state === 'working') {
    return <LoaderCircleIcon className='animate-spin' />;
  }
  if (state === 'done') {
    return <CheckIcon />;
  }
  return idleIcon;
}

type ActionButtonProps = Omit<ButtonProps, 'children'> & {
  state: ActionState;
  labels: ActionLabels;
  idleIcon?: React.ReactNode;
};

/** One button that becomes its next state: its icon swaps, its label crossfades and its width follows the new label. */
export function ActionButton({
  state,
  labels,
  idleIcon,
  ...props
}: ActionButtonProps) {
  const icon = iconOf(state, idleIcon);
  const hasIcon = Boolean(icon);
  const label = labels[state];
  const isWorking = state === 'working';
  const isDone = state === 'done';

  return (
    <>
      <Button aria-busy={isWorking} {...props}>
        {hasIcon && <Swap swapKey={state}>{icon}</Swap>}
        <AnimatedSize axis='width' as='span'>
          <Swap swapKey={label} kind='label'>
            {label}
          </Swap>
        </AnimatedSize>
      </Button>
      <span className='sr-only' role='status'>
        {isDone && labels.done}
      </span>
    </>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useId, useRef, useState } from 'react';

import { XIcon } from '@/registry/ndeko/lib/icons';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';

import {
  ADDRESS_LOOK,
  type AddressEntry,
  type AddressLook,
} from './invite-emails';
import { chipVariantsOf } from './motion';

export type FieldChip = { email: string; look: AddressLook };

export function chipsOf(entries: AddressEntry[]): FieldChip[] {
  return entries.map((entry) => ({
    email: entry.email,
    look: ADDRESS_LOOK[entry.state],
  }));
}

const COMMIT_KEYS = new Set(['Enter', ',', ';', ' ', 'Tab']);

function placeholderOf(hasChips: boolean, empty: string, more: string) {
  if (hasChips) {
    return more;
  }
  return empty;
}

function AddressChip({
  chip,
  allowsLayout,
  onRemove,
}: {
  chip: FieldChip;
  allowsLayout: boolean;
  onRemove: (email: string) => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const variants = chipVariantsOf(shouldReduceMotion);
  const ChipGlyph = chip.look.icon;
  const hasHint = chip.look.hint.length > 0;

  function remove() {
    onRemove(chip.email);
  }

  return (
    <motion.li
      layout={allowsLayout}
      variants={variants}
      initial='hidden'
      animate='shown'
      exit='hidden'
      title={chip.look.hint}
      className='flex max-w-full'
    >
      <Chip
        color={chip.look.color}
        className='h-6 max-w-full gap-1 pr-0.5 pl-1.5 text-xs'
      >
        {ChipGlyph && <ChipGlyph strokeWidth={2.25} />}
        <span className='truncate'>{chip.email}</span>
        {hasHint && <span className='sr-only'>{chip.look.hint}</span>}
        <button
          type='button'
          aria-label={`Remove ${chip.email}`}
          onClick={remove}
          className='hover:bg-foreground/10 focus-visible:ring-ring/25 flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-[5px] opacity-70 transition-[opacity,background-color] duration-150 outline-none hover:opacity-100 focus-visible:opacity-100 focus-visible:ring-[3px]'
        >
          <XIcon className='size-3' />
        </button>
      </Chip>
    </motion.li>
  );
}

type AddressFieldProps = {
  label: string;
  chips: FieldChip[];
  onAdd: (text: string) => void;
  onRemove: (email: string) => void;
  /** Enter on an empty line, or Cmd Enter at any time, sends what the field holds. */
  onSubmitShortcut?: () => void;
  /** Sits at the right end of the field, such as the role of the batch. */
  trailing?: React.ReactNode;
  placeholder?: string;
  morePlaceholder?: string;
  describedBy?: string;
  isInvalid?: boolean;
  disabled?: boolean;
  className?: string;
};

/**
 * One field for many addresses, like the To line of a mail: each address becomes a chip tinted by what sending
 * will do with it, a pasted list fills it at once, Backspace on an empty line takes the last chip back.
 */
export function AddressField({
  label,
  chips,
  onAdd,
  onRemove,
  onSubmitShortcut,
  trailing,
  placeholder = 'name@company.com, another@company.com',
  morePlaceholder = 'Add another address',
  describedBy,
  isInvalid = false,
  disabled = false,
  className,
}: AddressFieldProps) {
  const inputId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const [draft, setDraft] = useState('');
  const shouldReduceMotion = useReducedMotion();
  const allowsLayout = !shouldReduceMotion;
  const hasChips = chips.length > 0;
  const hasTrailing = Boolean(trailing);
  const shownPlaceholder = placeholderOf(
    hasChips,
    placeholder,
    morePlaceholder
  );
  const lastChip = chips.at(-1);

  function focusInput() {
    inputRef.current?.focus();
  }

  function commitDraft() {
    const typed = draft.trim();
    if (typed.length === 0) {
      return false;
    }
    onAdd(typed);
    setDraft('');
    return true;
  }

  function changeDraft(event: React.ChangeEvent<HTMLInputElement>) {
    setDraft(event.target.value);
  }

  function removeChip(email: string) {
    onRemove(email);
    focusInput();
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    const isEnter = event.key === 'Enter';
    const hasModifier = event.metaKey || event.ctrlKey;
    const isDraftEmpty = draft.trim().length === 0;
    const isSubmitShortcut = isEnter && hasModifier;
    const isEnterOnEmptyLine = isEnter && isDraftEmpty;
    const asksToSend = isSubmitShortcut || isEnterOnEmptyLine;
    if (asksToSend && onSubmitShortcut) {
      event.preventDefault();
      commitDraft();
      onSubmitShortcut();
      return;
    }
    if (COMMIT_KEYS.has(event.key)) {
      const hasCommitted = commitDraft();
      const isTab = event.key === 'Tab';
      const keepsTabMoving = isTab && !hasCommitted;
      if (!keepsTabMoving) {
        event.preventDefault();
      }
      return;
    }
    const isBackspace = event.key === 'Backspace';
    const takesLastChip = isBackspace && draft.length === 0;
    if (takesLastChip && lastChip) {
      onRemove(lastChip.email);
    }
  }

  function handlePaste(event: React.ClipboardEvent<HTMLInputElement>) {
    const pasted = event.clipboardData.getData('text');
    event.preventDefault();
    onAdd(`${draft} ${pasted}`);
    setDraft('');
  }

  return (
    <div
      role='presentation'
      onClick={focusInput}
      data-invalid={isInvalid || undefined}
      className={cn(
        CONTROL_RECIPE,
        'flex min-h-9 cursor-text items-start gap-1 p-1',
        'focus-within:border-foreground/30 focus-within:ring-ring/25 focus-within:ring-[3px]',
        className
      )}
    >
      <div className='relative flex max-h-[7rem] min-w-0 flex-1 flex-wrap items-center gap-1 overflow-y-auto overscroll-contain'>
        {hasChips && (
          <ul aria-label='Addresses to invite' className='contents'>
            <AnimatePresence initial={false} mode='popLayout'>
              {chips.map((chip) => (
                <AddressChip
                  key={chip.email}
                  chip={chip}
                  allowsLayout={allowsLayout}
                  onRemove={removeChip}
                />
              ))}
            </AnimatePresence>
          </ul>
        )}
        <label htmlFor={inputId} className='sr-only'>
          {label}
        </label>
        <input
          ref={inputRef}
          id={inputId}
          type='text'
          inputMode='email'
          autoComplete='off'
          spellCheck={false}
          value={draft}
          disabled={disabled}
          aria-describedby={describedBy}
          aria-invalid={isInvalid || undefined}
          placeholder={shownPlaceholder}
          onChange={changeDraft}
          onKeyDown={handleKeyDown}
          onPaste={handlePaste}
          onBlur={commitDraft}
          className='placeholder:text-muted-foreground/75 h-7 min-w-36 flex-1 bg-transparent px-1.5 text-base outline-none disabled:cursor-not-allowed md:text-[13px]'
        />
      </div>
      {hasTrailing && (
        <div className='flex h-7 shrink-0 items-center'>{trailing}</div>
      )}
    </div>
  );
}

import {
  AlertCircleIcon,
  ClockIcon,
  UserIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';

/** What sending does to an address: a new invitation, the e-mail again for a pending one, nothing for a member or a typo. */
export type AddressState = 'new' | 'pending' | 'member' | 'invalid';

export type AddressEntry = { email: string; state: AddressState };

export type AddressLook = { color: string; icon: Icon | null; hint: string };

export const ADDRESS_LOOK: Record<AddressState, AddressLook> = {
  new: { color: 'var(--muted-foreground)', icon: null, hint: '' },
  pending: {
    color: 'var(--warning)',
    icon: ClockIcon,
    hint: 'Already invited: they get the e-mail again',
  },
  member: {
    color: 'var(--muted-foreground)',
    icon: UserIcon,
    hint: 'Already in the team: not invited again',
  },
  invalid: {
    color: 'var(--destructive)',
    icon: AlertCircleIcon,
    hint: 'Not a valid e-mail address',
  },
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const TOKEN_SEPARATORS = /[\s,;<>"'()]+/;

export function isEmail(value: string) {
  return EMAIL_PATTERN.test(value);
}

function normalizeAddress(value: string) {
  const trimmed = value.trim();
  return trimmed.toLowerCase();
}

/**
 * The addresses in what was typed or pasted, without repeats. When the text holds an address, the words around it
 * are names copied from a mail client and are left out.
 */
export function splitAddresses(text: string) {
  const tokens = text.split(TOKEN_SEPARATORS);
  const holdsAnAddress = text.includes('@');
  const addresses: string[] = [];
  for (const token of tokens) {
    const address = normalizeAddress(token);
    const isEmpty = address.length === 0;
    const isNameAround = holdsAnAddress && !address.includes('@');
    const isRepeat = addresses.includes(address);
    if (isEmpty || isNameAround || isRepeat) {
      continue;
    }
    addresses.push(address);
  }
  return addresses;
}

export function mergeAddresses(current: string[], added: string[]) {
  const merged = [...current];
  for (const address of added) {
    if (!merged.includes(address)) {
      merged.push(address);
    }
  }
  return merged;
}

export type AddressContext = {
  memberEmails: ReadonlySet<string>;
  pendingEmails: ReadonlySet<string>;
};

export function stateOfAddress(
  email: string,
  context: AddressContext
): AddressState {
  if (!isEmail(email)) {
    return 'invalid';
  }
  if (context.memberEmails.has(email)) {
    return 'member';
  }
  if (context.pendingEmails.has(email)) {
    return 'pending';
  }
  return 'new';
}

export function isSendable(state: AddressState) {
  const isNew = state === 'new';
  const isPending = state === 'pending';
  return isNew || isPending;
}

export function countOf(entries: AddressEntry[], state: AddressState) {
  return entries.filter((entry) => entry.state === state).length;
}

